pub type Product = {
  id: Int;
  name: Str;
  price: Float64;
} derive[Eq, Hash, Ord, Clone]

fn main() -> Int {
  let inventory = Map[Product, Int]();
  let p1 = Product{ id: 1, name: "Widget", price: 9.99 };
  let p2 = Product{ id: 2, name: "Gadget", price: 19.99 };
  let p3 = Product{ id: 3, name: "Doohickey", price: 4.99 };
  inventory.insert(p1, 50);
  inventory.insert(p2, 25);
  inventory.insert(p3, 100);
  return inventory.get(&p1) + inventory.get(&p2) + inventory.get(&p3);
}
